def csv_rows(text):
    rows = []
    i = 0
    n = len(text)
    while i < n:
        row = []
        while True:
            # Parse a field
            if i < n and text[i] == '"':
                # Quoted field
                i += 1  # skip opening quote
                field_chars = []
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            # Doubled quote -> escaped quote
                            field_chars.append('"')
                            i += 2
                        else:
                            # Closing quote
                            i += 1
                            break
                    else:
                        field_chars.append(text[i])
                        i += 1
                row.append(''.join(field_chars))
            else:
                # Unquoted field
                field_chars = []
                while i < n and text[i] != ',' and text[i] != '\r' and text[i] != '\n':
                    field_chars.append(text[i])
                    i += 1
                row.append(''.join(field_chars))

            # After the field, check what comes next
            if i < n:
                if text[i] == ',':
                    i += 1  # skip comma, continue to next field in same row
                    continue
                elif text[i] == '\r':
                    # CRLF or CR
                    if i + 1 < n and text[i + 1] == '\n':
                        i += 2  # skip CRLF
                    else:
                        i += 1  # skip CR
                    break
                elif text[i] == '\n':
                    i += 1  # skip LF
                    break
                else:
                    # Should not happen in valid CSV, but break anyway
                    break
            else:
                # End of input
                break

        rows.append(row)
    return rows
